const kunden = $input.all();
const now = new Date();
const results = [];

for (const k of kunden) {
  if (k.json.status !== 'aktiv') continue;

  const letzteAktivitaet = new Date(k.json.letzte_aktivitaet || k.json.onboarding_am);
  const tageInaktiv = Math.floor((now - letzteAktivitaet) / (1000 * 60 * 60 * 24));

  // Vertragsende prüfen
  const vertragsende = k.json.vertragsende ? new Date(k.json.vertragsende) : null;
  const tageVertragsende = vertragsende ? Math.floor((vertragsende - now) / (1000 * 60 * 60 * 24)) : null;

  let aktion = null;
  if (tageInaktiv >= 14) aktion = 'inaktiv_checkin';
  if (tageVertragsende !== null && tageVertragsende <= 30 && tageVertragsende > 0) aktion = 'vertragsende_erinnerung';

  if (aktion) {
    results.push({ json: { ...k.json, aktion, tage_inaktiv: tageInaktiv, tage_vertragsende: tageVertragsende } });
  }
}

return results;

